void config_init(Config*c){memset(c,0,sizeof(*c));c->max_depth=64;c->max_func_len=200;c->max_params=6;c->check_level=3;c->threads=4;c->verbose=0;c->json=0;c->html=0;c->text=1;c->show_suggestions=1;c->show_context=1;c->max_issues=1000;c->output[0]=0;c->project_name[0]=0;c->root[0]=0;c->follow_symlinks=0;c->recursive=1;c->enable_all=1;c->suppress_all=0;c->nignore=0;c->default_checks=1;c->ci_mode=0;c->pedantic=0;c->quick=0;c->deep=0;c->show_all=0;c->group_by_category=0;c->group_by_file=0;c->group_by_severity=0;c->sort_by_severity=0;c->sort_by_file=0;c->sort_by_code=0;c->fail_on_error=0;c->warn_as_error=0;c->no_warn=0;c->only_errors=0;c->brief=0;c->full=0;c->color=1;c->no_color=0;c->format_json=0;c->format_html=0;c->format_text=1;c->format_sarif=0;c->format_checkstyle=0;c->stats=0;c->timing=0;c->progress=1;c->no_progress=0;c->quiet=0;c->silent=0;c->debug=0;c->trace=0;c->profile=0;c->diff_mode=0;c->fix=0;c->dry_run=0;c->force=0;c->no_cache=0;c->version=0;c->list_checks=0;c->list_languages=0;c->show_rules=0;c->focus_check[0]=0;c->skip_check[0]=0;c->severity_filter[0]=0;c->category_filter[0]=0;c->lang_filter[0]=0;c->exclude_lang[0]=0;c->include_pattern[0]=0;c->exclude_pattern[0]=0;c->max_files=0;c->max_line_length=0;c->tab_size=4;c->indent_style=0;c->encoding[0]=0;c->sequential=0;c->config_path[0]=0;c->dump_config=0;c->watch=0;c->continuous=0;c->init_config=0;c->explain_check=0;c->check_id[0]=0;c->rule_id[0]=0;c->no_default_checks=0;c->baseline=0;c->baseline_file=0;c->baseline_path[0]=0;c->update_baseline=0;c->suppress_warnings=0;c->suppress_info=0;c->suppress_rule[0]=0;c->show_suppressed=0;c->generate_config=0;c->fail_on_count=0;c->unused_include=1;c->duplicate_code=1;c->missing_doc=0;c->check_coverage=0;c->cyclomatic_complexity=0;c->cognitive_complexity=0;c->max_nesting=8;c->min_identifier_len=2;c->max_identifier_len=64;c->enforce_naming=0;c->code_format=0;}
